let db=Data.createEmptyDatabase(),activeDate=dateKey(),calendarMonth=dateKey().slice(0,7),lastToday=dateKey(),patrolHistoryWeek="",completionDateMode="today",selectedProjectId="",selectedCategoryId="",selectedWishListTab="all",outlookView="week",recurringSourceDraft=null,categoryProjectCollapsed=new Set(),hierarchyExpanded=new Set(),routineCategoryExpanded=new Set();
const persist=()=>Data.repository.save(db),isLive=x=>!x.deletedAt,taskDate=t=>t.completedAt?.slice(0,10);
