function modeDay(){return completionDateMode==="yesterday"?addDays(currentDay(),-1):currentDay()}
function setupCompletionModeControls(){for(const [page,list,anchor] of [["today","todayOverviewTasks",null],["capture","todayTasks",null],["routines",null,".routine-subnav"],["projects",null,"#projectViewTabs"]]){const section=list?$("#"+list)?.closest("section"):$("#"+page);if(!section||section.querySelector(".completion-mode-control"))continue;const control=document.createElement("div");control.className="completion-mode-control";control.innerHTML='<button type="button" class="completion-mode-button" aria-pressed="false">昨日モード：オフ</button><small class="completion-mode-label"></small>';section.insertBefore(control,list?section.querySelector(".section-title")?.nextSibling||section.firstChild:section.querySelector(anchor));control.querySelector("button").onclick=()=>{completionDateMode=completionDateMode==="today"?"yesterday":"today";renderAll()}}}
function renderCompletionMode(){const yesterday=addDays(currentDay(),-1);for(const page of ["today","capture","routines","projects"]){const section=$("#"+page),control=section?.querySelector(".completion-mode-control");if(!control)continue;const active=completionDateMode==="yesterday";control.classList.toggle("active",active);const button=control.querySelector("button");button.textContent=`昨日モード：${active?"オン":"オフ"}`;button.setAttribute("aria-pressed",String(active));control.querySelector("small").textContent=active?`${yesterday} の記録を編集します（今日のチェックは保持）`:`今日（${currentDay()}）の記録を編集します`;section.querySelectorAll('.complete[data-action="complete"]').forEach(item=>item.title=active?`${yesterday} の完了として記録`:"完了")}}

// Shared rendering helpers keep every task view tied to the same task record.
function approved(t){return isLive(t)&&t.approvalStatus!=="pending"&&t.recordKind!=="wish"}
function isWish(t){return isLive(t)&&t.recordKind==="wish"}
function options(kind,selected=""){const items=kind==="categories"?orderedCategories():db[kind].filter(isLive);return '<option value="">指定なし</option>'+items.map(x=>`<option value="${x.id}" ${x.id===selected?"selected":""}>${esc(x.name)}</option>`).join("")}
function projectOptions(categoryId="",selected=""){const projects=categoryId?orderedProjects(categoryId):db.projects.filter(isLive).sort(displayOrder);return '<option value="">指定なし</option>'+projects.map(p=>`<option value="${p.id}" ${p.id===selected?"selected":""}>${esc(p.name)}</option>`).join("")}
function metaFor(t){return [nameOf("categories",t.categoryId,true),nameOf("projects",t.projectId,true),isThisWeek(t)?"今週":"",isThisMonth(t)?"今月":"",t.source==="ai"?"AI登録":""].filter(Boolean).map(x=>`<span>${esc(x)}</span>`).join("")}
function menuHtml(review=false){return `<div class="menu"><button class="more" data-action="menu" aria-label="操作">•••</button><div class="menu-panel" hidden><button data-action="edit-task">タスクカードを開く</button>${review?'<button data-action="change-date">完了日を直す</button>':""}<button class="danger" data-action="delete">削除する</button></div></div>`}
function taskHtml(t,{review=false,complete=false}={}){return `<article class="item" data-task-id="${t.id}">${complete?'<button class="complete" data-action="complete" title="完了">✓</button>':""}<div class="item-body"><p class="item-title">${esc(t.title)}</p><div class="meta">${metaFor(t)}</div></div>${menuHtml(review)}</article>`}
function journalHtml(j){const theme=nameOf("themes",j.themeId,true),category=nameOf("journalCategories",j.journalCategoryId,true),editable=j.journalKind==="one_line";return `<article class="item journal-item ${editable?"one-line-journal-item":""}" data-journal-id="${j.id}"><div><div class="meta"><span>${esc(j.entryDate)}</span><span>${new Date(j.createdAt).toLocaleTimeString("ja-JP",{hour:"2-digit",minute:"2-digit"})}</span>${theme?`<span>テーマ：${esc(theme)}</span>`:""}${category?`<span>一行日記：${esc(category)}</span>`:""}</div>${editable?`<button class="journal-text journal-edit-button" data-action="edit-one-line">${esc(j.text)}</button>`:`<p class="journal-text">${esc(j.text)}</p>`}</div><div class="menu"><button class="more" data-action="menu">•••</button><div class="menu-panel" hidden><button class="danger" data-action="delete-journal">削除する</button></div></div></article>`}
function taskActions(task){return `<div class="button-row"><button class="period-check ${isThisWeek(task)?"active":""}" data-action="star" data-period="week" title="今週">W</button><button class="period-check ${isThisMonth(task)?"active":""}" data-action="star" data-period="month" title="今月">M</button><button class="star ${task.todayDate===currentDay()?"active":""}" data-action="star" data-period="today" title="今日">${task.todayDate===currentDay()?"★":"☆"}</button>${menuHtml()}</div>`}
function openTaskRow(t){return `<article class="item" data-task-id="${t.id}"><button class="complete" data-action="complete" title="完了">✓</button><div class="item-body"><button class="task-title-button" data-action="edit-task">${esc(t.title)}</button><div class="meta">${metaFor(t)}</div></div>${taskActions(t)}</article>`}
function backlogHierarchyHtml(tasks){const rows=[],liveCategoryIds=new Set(orderedCategories().map(c=>c.id)),renderGroup=(title,items,level="category")=>{if(items.length)rows.push(`<section class="backlog-group ${level}"><h3>${esc(title)}<span>${items.length}件</span></h3><div class="stack">${newest(items).map(openTaskRow).join("")}</div></section>`)};for(const category of orderedCategories()){const categoryTasks=tasks.filter(t=>t.categoryId===category.id),projects=orderedProjects(category.id),projectIds=new Set(projects.map(p=>p.id));if(!categoryTasks.length)continue;rows.push(`<div class="backlog-category-title">${esc(category.name)}</div>`);for(const project of projects)renderGroup(project.name,categoryTasks.filter(t=>t.projectId===project.id),"project");renderGroup("プロジェクトなし",categoryTasks.filter(t=>!projectIds.has(t.projectId)),"project")}const uncategorized=tasks.filter(t=>!liveCategoryIds.has(t.categoryId)),projects=orderedProjects(""),projectIds=new Set(projects.map(p=>p.id));if(uncategorized.length){rows.push('<div class="backlog-category-title">未分類</div>');for(const project of projects)renderGroup(project.name,uncategorized.filter(t=>t.projectId===project.id),"project");renderGroup("プロジェクトなし",uncategorized.filter(t=>!projectIds.has(t.projectId)),"project")}return rows.join("")}
function renderTasks(){const today=currentDay(),open=newest(db.tasks.filter(t=>approved(t)&&t.status!=="done")),starred=open.filter(t=>t.todayDate===today),backlog=open.filter(t=>t.todayDate!==today),view=db.settings.backlogView||"newest";$("#todayLabel").textContent=new Date(today+"T12:00:00").toLocaleDateString("ja-JP",{month:"long",day:"numeric",weekday:"short"});$("#todayCount").textContent=starred.length+"件";$("#backlogCount").textContent=backlog.length+"件";$("#todayTasks").innerHTML=starred.length?starred.map(openTaskRow).join(""):"<div class='empty'>星を付けたタスクが、ここに並びます。</div>";$("#backlogTasks").classList.toggle("backlog-grouped",view==="hierarchy");$("#backlogTasks").innerHTML=backlog.length?(view==="hierarchy"?backlogHierarchyHtml(backlog):backlog.map(openTaskRow).join("")):"<div class='empty'>次にやることはありません。</div>";$$('[data-backlog-view]').forEach(button=>{const active=button.dataset.backlogView===view;button.classList.toggle("active",active);button.setAttribute("aria-pressed",String(active))})}
function orderedWishLists(){return db.wishLists.filter(isLive).sort(displayOrder)}
function wishListOptions(selected=""){return '<option value="">リスト未設定</option>'+orderedWishLists().map(list=>`<option value="${list.id}" ${list.id===selected?"selected":""}>${esc(list.name)}</option>`).join("")}
