function renderRecurringRules(){const rows=db.recurringRules.filter(isLive);const labels={daily:"毎日",weekly:"毎週",monthly:"毎月",interval:"日ごと"};$("#recurringRuleList").innerHTML=rows.length?rows.map(rule=>{let schedule=labels[rule.frequency];if(rule.frequency==="weekly")schedule+=`（${rule.daysOfWeek.map(day=>"日月火水木金土"[day]).join("・")}）`;if(rule.frequency==="monthly")schedule+=` ${rule.dayOfMonth}日`;if(rule.frequency==="interval")schedule=`${rule.interval}日ごと`;const context=[nameOf("categories",rule.categoryId,true),nameOf("projects",rule.projectId,true)].filter(Boolean);return `<article class="item" data-rule-id="${rule.id}"><div class="item-body"><p class="item-title">${esc(rule.title)}</p><div class="meta"><span>${schedule}</span><span>${rule.startDate}から</span>${context.map(value=>`<span>${esc(value)}</span>`).join("")}${rule.active?"":"<span>停止中</span>"}</div></div><div class="button-row"><button class="more" data-action="edit-recurring">編集</button><button class="secondary-button" data-action="toggle-recurring">${rule.active?"停止":"再開"}</button></div></article>`}).join(""):"<div class='empty'>繰り返し設定はありません。</div>"}
function pendingTaskHtml(t){return `<article class="item" data-task-id="${t.id}"><div class="item-body"><p class="item-title">${esc(t.title)}</p><div class="meta"><span>新規タスク</span>${metaFor(t)}</div></div><div class="button-row"><button class="secondary-button" data-action="approve-pending">承認</button><button class="more danger" data-action="reject-pending">削除</button></div></article>`}
function changeValueLabel(field,value){if(field==="categoryId")return nameOf("categories",value)||"指定なし";if(field==="projectId")return nameOf("projects",value)||"指定なし";if(field==="priority")return ({none:"指定なし",low:"低",medium:"中",high:"高",urgent:"至急"})[value]||"指定なし";if(field==="estimateMinutes")return value?value+"分":"指定なし";if(["weekStatusKey","monthStatusKey"].includes(field))return value?"チェックあり":"チェックなし";return value||"指定なし"}
function pendingChangeHtml(c){const task=db.tasks.find(t=>t.id===c.taskId),labels={categoryId:"カテゴリ",projectId:"プロジェクト",description:"詳細",startDate:"とりかかり日",dueDate:"締め切り日",priority:"優先順位",estimateMinutes:"見積もり時間",weekStatusKey:"今週",monthStatusKey:"今月"},kind=labels[c.field]||c.field;return `<article class="item" data-change-id="${c.id}"><div class="item-body"><p class="item-title">${esc(task?.title||"対象タスクなし")}</p><div class="meta"><span>変更提案</span><span>${esc(kind)}：${esc(changeValueLabel(c.field,c.fromValue))} → ${esc(changeValueLabel(c.field,c.toValue))}</span></div></div><div class="button-row"><button class="secondary-button" data-action="approve-change">承認</button><button class="more danger" data-action="reject-change">削除</button></div></article>`}
function renderPending(){const tasks=db.tasks.filter(t=>isLive(t)&&t.approvalStatus==="pending"),changes=db.aiChanges.filter(c=>c.status==="pending");$("#inboxBadge").hidden=!(tasks.length+changes.length);$("#inboxBadge").textContent=tasks.length+changes.length;$("#approveAll").disabled=!(tasks.length+changes.length);$("#pendingItems").innerHTML=tasks.length+changes.length?[...tasks.map(pendingTaskHtml),...changes.map(pendingChangeHtml)].join(""):"<div class='empty'>未承認の項目はありません。</div>"}
function renderDeleted(){const rows=[...db.tasks.filter(x=>x.deletedAt).map(x=>({...x,kind:"task",label:x.title,kindLabel:x.recordKind==="wish"?"Wish":"タスク"})),...db.journals.filter(x=>x.deletedAt).map(x=>({...x,kind:"journal",label:x.text,kindLabel:"日記"})),...db.contextNotes.filter(x=>x.deletedAt).map(x=>({...x,kind:"contextNote",label:x.text,kindLabel:"メモ"}))].sort((a,b)=>b.deletedAt.localeCompare(a.deletedAt));$("#deletedItems").innerHTML=rows.length?rows.map(x=>`<article class="item" data-id="${x.id}" data-kind="${x.kind}"><div class="item-body"><p class="item-title">${esc(x.label)}</p><div class="meta"><span>${x.kindLabel}</span></div></div><div class="button-row"><button class="secondary-button" data-action="restore">復元</button><button class="more danger" data-action="purge">完全削除</button></div></article>`).join(""):"<div class='empty'>削除済みの記録はありません。</div>";$("#purgeAllDeleted").disabled=!rows.length}
