function patrolPlaces(activeOnly=false){return db.patrolPlaces.filter(p=>isLive(p)&&(!activeOnly||p.active)).sort((a,b)=>(a.order||0)-(b.order||0))}
function patrolCheck(placeId,day){return db.patrolChecks.find(c=>c.patrolPlaceId===placeId&&c.businessDate===day)}
function patrolLastDay(place){const checked=db.patrolChecks.filter(c=>c.patrolPlaceId===place.id&&c.checked).sort((a,b)=>b.businessDate.localeCompare(a.businessDate))[0];return checked?.businessDate||Data.businessDateKey(db.settings,new Date(place.createdAt))}
function patrolStaleDays(place){return Math.max(0,dayDiff(patrolLastDay(place),currentDay()))}
function patrolTrackerHtml(start,places,editable=false){const today=currentDay(),days=Array.from({length:7},(_,i)=>addDays(start,i)),names=["日","月","火","水","木","金","土"];return `<div class="patrol-grid"><div class="patrol-grid-corner">巡回場所</div>${days.map(day=>{const d=new Date(day+"T12:00:00");return `<div class="patrol-day-head ${day===today?"today":""}"><span>${names[d.getDay()]}</span><small>${d.getDate()}</small></div>`}).join("")}${places.map(place=>{const stale=patrolStaleDays(place)>=3&&!patrolCheck(place.id,today)?.checked,createdDay=Data.businessDateKey(db.settings,new Date(place.createdAt));return `<div class="patrol-place-name ${stale?"stale":""}"><span>${esc(place.name)}</span><small>${stale?`最終${patrolStaleDays(place)}日前`:""}</small></div>${days.map(day=>{const check=patrolCheck(place.id,day),future=day>today,before=day<createdDay,state=check?.checked?"done":future||before?"future":"miss",late=Boolean(check?.checked&&check.backfilled),label=check?.checked?(late?"後から記録 ":"")+new Date(check.checkedAt).toLocaleTimeString("ja-JP",{hour:"2-digit",minute:"2-digit"}):before?"登録前":future?"未来":"未確認",content=state==="done"?(late?"✓*":"✓"):state==="miss"?"○":"·",classes=`patrol-cell ${state} ${late?"backfilled":""} ${day===today?"today":""}`;return editable&&!future&&!before?`<button type="button" class="${classes}" data-action="toggle-patrol-date" data-id="${place.id}" data-day="${day}" title="${esc(day+" "+label)}">${content}</button>`:`<div class="${classes}" title="${esc(day+" "+label)}">${content}</div>`}).join("")}`}).join("")}</div>`}
function renderPatrol(){const day=modeDay(),active=patrolPlaces(true),done=active.filter(place=>patrolCheck(place.id,day)?.checked).length;$("#patrolTodayCount").textContent=`${done}/${active.length}`;$("#patrolTodayList").innerHTML=active.length?active.map(place=>{const check=patrolCheck(place.id,day),checked=check?.checked,stale=patrolStaleDays(place)>=3&&!checked;return `<button class="patrol-check-row ${checked?"checked":""} ${stale?"stale":""}" data-action="toggle-patrol" data-id="${place.id}"><span class="patrol-check-mark">${checked?"✓":""}</span><strong>${esc(place.name)}</strong><small>${checked?new Date(check.checkedAt).toLocaleTimeString("ja-JP",{hour:"2-digit",minute:"2-digit"}):stale?`最終${patrolStaleDays(place)}日前`:"未確認"}</small></button>`}).join(""):"<div class='empty compact-empty'>巡回管理から巡回場所を追加できます。</div>";$("#capture .patrol-today h2").textContent=completionDateMode==="yesterday"?`昨日の巡回（${day}）`:"今日の巡回";$("#patrolWeekTracker").innerHTML=active.length?patrolTrackerHtml(currentWeek(),active):"<div class='empty compact-empty'>巡回場所はまだありません。</div>"}
function renderPatrolManage(){if(!patrolHistoryWeek)patrolHistoryWeek=currentWeek();const places=patrolPlaces(),start=patrolHistoryWeek,end=addDays(start,6);$("#patrolHistoryTitle").textContent=`${Number(start.slice(5,7))}/${Number(start.slice(8))}～${Number(end.slice(5,7))}/${Number(end.slice(8))}`;$("#nextPatrolWeek").disabled=start>=currentWeek();$("#patrolHistoryTracker").innerHTML=places.length?patrolTrackerHtml(start,places,true)+"<small class='patrol-backfill-note'>* 後から記録したチェック</small>":"<div class='empty compact-empty'>巡回場所はまだありません。</div>";$("#patrolPlaceList").innerHTML=places.length?places.map((place,index)=>{const hasHistory=db.patrolChecks.some(c=>c.patrolPlaceId===place.id);return `<article class="item patrol-place-admin ${place.active?"":"ended"}" data-patrol-id="${place.id}"><div class="item-body"><p class="item-title">${esc(place.name)}</p><div class="meta"><span>${place.active?"使用中":"使用終了"}</span></div></div><div class="button-row"><button class="more" data-action="move-patrol-up" ${index===0?"disabled":""}>↑</button><button class="more" data-action="move-patrol-down" ${index===places.length-1?"disabled":""}>↓</button><button class="more" data-action="rename-patrol">編集</button><button class="secondary-button" data-action="toggle-patrol-active">${place.active?"終了":"再開"}</button>${hasHistory?"":'<button class="more danger" data-action="delete-patrol">削除</button>'}</div></article>`}).join(""):"<div class='empty'>巡回場所はまだありません。</div>"}
