function reconcileRoutines(){const today=currentDay();for(const routine of db.routines){if(routine.dailyDate===today)continue;routine.dailyDate=today;routine.dailyState="undecided";routine.dailyOrder=null}}
function routineLabel(routine){return routine.itemType==="category"?(nameOf("categories",routine.categoryId,true)||routine.title):routine.title}
function routineCategoryContent(routine){if(routine.itemType!=="category")return "";const projects=newest(db.projects.filter(p=>isLive(p)&&p.categoryId===routine.categoryId)),direct=newest(db.tasks.filter(t=>approved(t)&&t.status!=="done"&&!t.projectId&&t.categoryId===routine.categoryId));const rows=tasks=>tasks.length?`<div class="stack">${tasks.map(openTaskRow).join("")}</div>`:'<small class="meta">未完了タスクなし</small>';return `<div class="routine-category-content"><section><strong>プロジェクトなし</strong>${rows(direct)}</section>${projects.map(p=>`<section><strong>${esc(p.name)}</strong>${rows(newest(db.tasks.filter(t=>approved(t)&&t.status!=="done"&&t.projectId===p.id)))}</section>`).join("")}</div>`}
function routineCard(routine){const selected=Number.isInteger(routine.dailyOrder),completed=routine.dailyState==="completed",skipped=routine.dailyState==="skipped",badge=selected?`<span class="routine-number">${routine.dailyOrder}</span>`:'<span class="routine-number empty-number"></span>',category=routine.itemType==="category",open=routineCategoryExpanded.has(routine.id);return `<article class="routine-card card ${selected?"selected":""} ${completed?"completed":""} ${skipped?"skipped":""}" data-routine-id="${routine.id}"><button class="routine-select" data-action="select-routine">${badge}<span><strong>${esc(routineLabel(routine))}</strong>${routine.description?`<small>${esc(routine.description)}</small>`:""}</span></button><button class="routine-skip ${skipped?"active":""}" data-action="skip-routine">${skipped?"やらない ✓":"今日はやらない"}</button>${category?`<button class="routine-details" data-action="toggle-routine-category">${open?"内容を隠す":"内容を見る"}</button>${open?routineCategoryContent(routine):""}`:""}</article>`}
function renderRoutines(){const today=currentDay(),routines=db.routines.filter(r=>isLive(r)&&r.active).sort((a,b)=>a.idealOrder-b.idealOrder),todayTasks=newest(db.tasks.filter(t=>approved(t)&&t.status!=="done"&&(t.todayDate===today||t.dueDate===today||t.startDate===today))),selected=routines.filter(r=>r.dailyState==="selected").sort((a,b)=>a.dailyOrder-b.dailyOrder);$("#routineDate").textContent=new Date(today+"T12:00:00").toLocaleDateString("ja-JP",{month:"long",day:"numeric",weekday:"short"});$("#routineTodayView").innerHTML=`<section class="routine-task-reference"><div class="section-title"><h2>今日の予定・タスク</h2><span class="count">${todayTasks.length}件</span></div><div class="routine-task-chips">${todayTasks.length?todayTasks.map(t=>`<span>${esc(t.title)}</span>`).join(""):"<span class='meta'>今日指定のタスクはありません。</span>"}</div></section><div class="section-title"><div><h2>理想のルーティン</h2><small>やる順番にカードをタップしてください。</small></div><button class="more" data-action="clear-routine-plan" ${selected.length?"":"disabled"}>選択を解除</button></div><div class="routine-list">${routines.length?routines.map(routineCard).join(""):'<div class="empty">ルーティンはまだありません。登録・設定から追加できます。</div>'}</div>`;$("#routineManageList").innerHTML=routines.length?routines.map((r,index)=>`<article class="item" data-routine-id="${r.id}"><div class="item-body"><p class="item-title">${esc(r.title)}</p><div class="meta"><span>理想順 ${index+1}</span></div></div><div class="button-row"><button class="more" data-action="move-routine-up" ${index===0?"disabled":""}>↑</button><button class="more" data-action="move-routine-down" ${index===routines.length-1?"disabled":""}>↓</button><button class="more" data-action="edit-routine">編集</button><button class="more danger" data-action="delete-routine">削除</button></div></article>`).join(""):'<div class="empty">ルーティンはまだありません。</div>'}
function renderRoutineCategoryPicker(){const select=$("#routineCategorySelect"),add=$("#routineCategoryAdd");if(!select)return;const used=new Set(db.routines.filter(r=>isLive(r)&&r.itemType==="category").map(r=>r.categoryId)),available=newest(db.categories.filter(c=>isLive(c)&&!used.has(c.id)));select.innerHTML=available.length?available.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join(""):'<option value="">追加できるカテゴリはありません</option>';add.disabled=!available.length;for(const row of $$("#routineManageList [data-routine-id]")){const routine=db.routines.find(r=>r.id===row.dataset.routineId);if(!routine||routine.itemType!=="category")continue;row.querySelector(".item-title").textContent=routineLabel(routine);row.querySelector('[data-action="edit-routine"]')?.remove()}}
function renderRoutineExecution(){const view=$("#routineExecuteView");if(!view)return;const active=db.routines.filter(r=>isLive(r)&&r.active),hasPlan=active.some(r=>Number.isInteger(r.dailyOrder)),yesterday=completionDateMode==="yesterday",execution=yesterday?[...active].sort((a,b)=>a.idealOrder-b.idealOrder):todayExecution(),done=execution.filter(routineCompleted).length;view.innerHTML=`<div class="section-title"><div><h2>${yesterday?`昨日（${modeDay()}）の実行記録`:"今日の実行順"}</h2><small>${yesterday?"理想の順番で表示します。チェックのみ昨日分として保存します。":hasPlan?"今日指定した順番です。":"理想の順番を表示しています。"}</small></div><span class="count">${done}/${execution.length} 完了</span></div><div class="routine-execute-list">${execution.length?execution.map((r,index)=>`<article class="routine-execute-wrap"><button class="routine-execute-card card ${routineCompleted(r)?"completed":""}" data-action="complete-routine" data-routine-id="${r.id}"><span class="routine-number">${yesterday?index+1:r.dailyOrder||index+1}</span><span><strong>${esc(routineLabel(r))}</strong>${r.description?`<small>${esc(r.description)}</small>`:""}</span><span class="routine-complete-mark">${routineCompleted(r)?"✓ 完了":"タップで完了"}</span></button>${r.itemType==="category"?routineCategoryContent(r):""}</article>`).join(""):'<div class="empty">今日実行するルーティンはありません。</div>'}</div>`;const clear=$("#routineTodayView [data-action='clear-routine-plan']");if(clear)clear.disabled=!hasPlan}
